query_sede_park <- paste0(part_a, ' OR ', part_b)

# Replace preset searches for Park with Sede e Park
txt <- gsub('"Campus Park"', '"Sede e Park"', txt, fixed = TRUE)
txt <- gsub(', "Park", now, now', ', "Sede e Park", now, now', txt, fixed = TRUE)

# Also update the query text for Campus Park / Sede e Park in seed_saved_searches & migrate_buscas_salvas_campus
old_park_q <- '("deep tech" OR startup OR scaleup OR spin-off OR spinout OR entrepreneurship OR empreendedorismo OR "innovation ecosystem" OR "innovation hub" OR "technology park" OR "science park" OR "open innovation" OR "inovação aberta" OR "corporate innovation" OR "corporate venture capital" OR CVC OR "venture capital" OR VC OR "venture building" OR "business incubation" OR incubator OR incubadora OR accelerator OR aceleradora OR sandbox OR testbed OR "living lab" OR "proof of concept" OR POC OR "minimum viable product" OR MVP OR "technology commercialization" OR commercialization OR "technology transfer" OR "startup funding" OR "innovation challenge" OR "innovation competition" OR "entrepreneurial ecosystem" OR "technology venture" OR "research commercialization")'

txt <- gsub(old_park_q, query_sede_park, txt, fixed = TRUE)

# Add migration execution line in migrate_buscas_salvas_campus to auto-update existing DB records
migration_code <- '  try(DBI::dbExecute(conn, "UPDATE buscas_salvas SET nome_busca = \'Sede e Park\', campus = \'Sede e Park\' WHERE nome_busca = \'Campus Park\' OR campus = \'Park\'"), silent = TRUE)'

if (!any(grepl("UPDATE buscas_salvas SET nome_busca = 'Sede e Park'", txt, fixed = TRUE))) {
  idx <- grep("migrate_buscas_salvas_campus <- function", txt)
  if (length(idx) > 0) {
    txt <- c(txt[1:idx[1]], migration_code, txt[(idx[1]+1):length(txt)])
  }
}

writeLines(txt, db_path, useBytes = TRUE)
cat("Updated helpers_db.R successfully\n")
